There are so many ways to do this and internally we have come to a solution similar to this:
```
std::string getRandomString(bool isUsername)
{
    std::string uniqueStr{};
    constexpr size_t pwLen = 16;
    uniqueStr.reserve(pwLen);
    std::random_device rd;
    std::mt19937 generator(rd());

    constexpr auto charsets = std::to_array<std::string_view>({
        // usernames must start with one of these two classes
        {"ABCDEFGHIJKLMNOPQRSTUVWXYZ"},
        {"abcdefghijklmnopqrstuvwxyz"},
        // these two classes are only for passwords
        {"0123456789"},
        {"!#$%&()*+,-./:;<=>?@[]^_{|}~"},
        // this class is used instead of the prior two for usernames
        {"0123456789_-"},
    });
    constexpr size_t charsetUpper = 0;
    constexpr size_t charsetLower = 1;
    constexpr size_t charsetPasswordNumber = 2;
    constexpr size_t charsetPasswordPunctuation = 3;
    constexpr size_t charsetUsernameOther = 4;

    std::uniform_real_distribution<> distribution(0, 1);
    std::bitset<charsets.size()> charClasses{};
    if (isUsername)
    {
        // usernames must start with alpha
        charClasses[charsetPasswordNumber] = 1;
        charClasses[charsetPasswordPunctuation] = 1;
        charClasses[charsetUsernameOther] = 1;
    }
    else
    {
        charClasses[charsetUsernameOther] = 1;
    }
    char lastChar = '\0';
    while (uniqueStr.size() < pwLen)
    {
        std::string charset{};
        for (size_t i = 0; i < charsets.size(); i++)
        {
            if (!charClasses[i] || charClasses.all())
            {
                charset += charsets[i];
            }
        }
        char newChar{};
        while (true)
        {
            newChar = charset[static_cast<size_t>(
                floor(charset.size() * distribution(generator)))];

            // limit total number duplicates of each char
            if (std::count(uniqueStr.begin(), uniqueStr.end(), newChar) > 1)
            {
                continue;
            }

            // limit monotonic runs of chars
            if (abs(lastChar - newChar) > 1)
            {
                uniqueStr += newChar;
                break;
            }
        }
        std::print(stderr, "[{:02d}]: {}, {} ({} {})\n", uniqueStr.size(),
                   charClasses.to_string(), uniqueStr, lastChar, newChar);
        lastChar = newChar;
        for (size_t i = 0; i < charsets.size(); i++)
        {
            if (!charClasses[i])
            {
                if (charsets[i].find(newChar) != std::string_view::npos)
                {
                    charClasses[i] = 1;
                }
            }
        }
        if (charClasses.all())
        {
            charClasses.reset();
            if (isUsername)
            {
                // skip the password charsets
                charClasses[charsetPasswordPunctuation] = 1;
                charClasses[charsetPasswordNumber] = 1;
            }
            else
            {
                // skip the username charset
                charClasses[charsetUsernameOther] = 1;
            }
        }
    }
    return uniqueStr;
}
```

The reasons that I like this algorithm are:
1) It is relatively simple
2) It is unlikely to end up with a long runtime
3) It forces the use of multiple character classes, but not in any given order
4) The results are known to match the expected output; no need to check
5) It limits repeats and runs, but not in a way that strips too much entropy away
6) It uses c++ random machinery

It can be called to generate a username that is guaranteed to be a valid Linux username. It can be called to generate a password that is more complex with a wider variety of characters. This single function can replace most of the code in this file.
